const inputData = $input.first().json.body || $input.first().json;
const recipientPhone = inputData.recipient_phone || 'Desconocido';
const rawMessage = inputData.message || '';
const timestamp = new Date().toISOString();

let eventType = 'AVISO_GENERAL';
let colorCode = 3447003; // Azul estándar

if (rawMessage.toLowerCase().includes('confirmad')) {
  eventType = 'CITA_CONFIRMADA';
  colorCode = 3066993; // Verde
} else if (rawMessage.toLowerCase().includes('cancelad')) {
  eventType = 'CITA_CANCELADA';
  colorCode = 15158332; // Rojo urgente
} else if (rawMessage.toLowerCase().includes('reagendad') || rawMessage.toLowerCase().includes('cambiado')) {
  eventType = 'CITA_REAGENDADA';
  colorCode = 15844367; // Naranja
} else if (rawMessage.toLowerCase().includes('agendad') || rawMessage.toLowerCase().includes('creada')) {
  eventType = 'CITA_NUEVA';
  colorCode = 3447003;
}

return [{
  json: {
    evento: eventType,
    telefono: recipientPhone,
    mensaje: rawMessage,
    canal: 'WhatsApp / SMS',
    fechaProcesamiento: timestamp,
    esCancelacion: eventType === 'CITA_CANCELADA',
    colorDiscord: colorCode,
    asuntoCorreo: `[Aviso Clínico] ${eventType.replace('_', ' ')}`,
    estado: 'PROCESADO'
  }
}];

